//refAssemblies: TCAdmin.SDK.dll, TCAdmin.GameHosting.SDK.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll, TCAdmin.Web.Shared.dll, System.Net.Http.dll, System.IO.Compression.dll, System.IO.Compression.ZipFile.dll, System.Diagnostics.Process.dll
using System;
using System.IO;
using System.IO.Compression;
using System.Net.Http;
using System.Diagnostics;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// SCUM dependency provisioning (standalone — this official config carries its own deps and
// does not rely on the shared "Install VC++/DirectX" global scripts).
//   * Linux host  -> SCUM runs under Wine. Install the VC++/D3D runtimes it links against
//                    into the service's Wine prefix via winetricks. windows-kill.exe is a
//                    Windows-only tool and is NOT needed here — the BeforeServiceStopped
//                    script sends a native SIGINT on Linux.
//   * Windows host -> download windows-kill.exe (used by the BeforeServiceStopped Ctrl+C script).
// Marked Windows in the blueprint so the script DB-filter (which keys on the GAME OS) fetches
// it on a Wine host; the host check below routes to the correct branch.

string root = ThisService.RootDirectory;

if (System.OperatingSystem.IsLinux())
{
    string prefix = Path.Combine(root, ".wine");
    string marker = Path.Combine(prefix, ".tcadmin-winedeps");
    if (File.Exists(marker))
    {
        ScriptConsole.WriteLine("[scum-deps] Wine runtimes already installed in the prefix.");
        return;
    }

    ScriptConsole.WriteLine("[scum-deps] Installing VC++/D3D runtimes into the Wine prefix via winetricks (can take a few minutes)...");

    string b = string.Join(" ",
        "set -e;",
        $"ROOT='{root}';",
        "PREFIX=\"$ROOT/.wine\";",
        "MARKER=\"$PREFIX/.tcadmin-winedeps\";",
        "OWNER=$(stat -c '%U' \"$ROOT\");",
        "echo \"[scum-deps] service user: $OWNER\";",
        "RT=\"$ROOT/.tca/xdg-runtime\"; mkdir -p \"$RT\"; chmod 700 \"$RT\"; chown \"$OWNER\" \"$RT\";",
        "runuser -u \"$OWNER\" -- env WINEPREFIX=\"$PREFIX\" HOME=\"$ROOT\" XDG_RUNTIME_DIR=\"$RT\" WINEARCH=win64 WINEDEBUG=-all WINEDLLOVERRIDES='mscoree=;mshtml=' xvfb-run -a winetricks -q vcrun2019 d3dcompiler_47;",
        "touch \"$MARKER\"; chown \"$OWNER\" \"$MARKER\";",
        "echo '[scum-deps] winetricks finished';");

    var psi = new ProcessStartInfo
    {
        FileName = "/bin/bash",
        UseShellExecute = false,
        RedirectStandardOutput = true,
        RedirectStandardError = true,
    };
    psi.ArgumentList.Add("-c");
    psi.ArgumentList.Add(b);

    using (var p = Process.Start(psi))
    {
        string outText = await p.StandardOutput.ReadToEndAsync();
        string errText = await p.StandardError.ReadToEndAsync();
        await p.WaitForExitAsync();
        if (!string.IsNullOrWhiteSpace(outText))
            ScriptConsole.WriteLine(outText.Length > 2500 ? outText.Substring(outText.Length - 2500) : outText);
        if (!string.IsNullOrWhiteSpace(errText))
            ScriptConsole.WriteLine("[scum-deps stderr] " + (errText.Length > 1000 ? errText.Substring(errText.Length - 1000) : errText));
        ScriptConsole.WriteLine($"[scum-deps] winetricks exit code: {p.ExitCode}");
    }
    return;
}

// Native Windows: download windows-kill.exe into the service root for the Ctrl+C stop script.
const string url = "https://github.com/ElyDotDev/windows-kill/releases/download/1.1.4/windows-kill_1.1.4_release.zip";
const string entryPath = "windows-kill_x64_1.1.4_lib_release/windows-kill.exe";

string targetDir = root;
Directory.CreateDirectory(targetDir);
string targetExe = Path.Combine(targetDir, "windows-kill.exe");
if (File.Exists(targetExe))
{
    ScriptConsole.WriteLine("windows-kill.exe already present; skipping download.");
    return;
}

string zipPath = Path.Combine(targetDir, "windows-kill_1.1.4_release.zip");

ScriptConsole.WriteLine($"Downloading {url}");
using (var http = new HttpClient())
{
    byte[] data = await http.GetByteArrayAsync(url, ThisCancellationToken);
    await File.WriteAllBytesAsync(zipPath, data, ThisCancellationToken);
}
ScriptConsole.WriteLine($"Downloaded to {zipPath}");

using (ZipArchive archive = ZipFile.OpenRead(zipPath))
{
    ZipArchiveEntry entry = archive.GetEntry(entryPath);
    if (entry == null)
        throw new Exception($"Entry '{entryPath}' not found in the archive.");
    entry.ExtractToFile(targetExe, overwrite: true);
}
ScriptConsole.WriteLine($"Extracted windows-kill.exe to {targetExe}");

try
{
    File.Delete(zipPath);
    ScriptConsole.WriteLine($"Deleted archive {zipPath}");
}
catch (Exception ex)
{
    ScriptConsole.WriteLine($"Warning: could not delete zip file: {ex.Message}");
}

//refAssemblies: TCAdmin.SDK.dll, TCAdmin.GameHosting.SDK.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll, TCAdmin.Web.Shared.dll, System.Diagnostics.Process.dll
using System;
using System.Diagnostics;
using System.IO;
using System.Threading;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// SCUM must receive ONE Ctrl+C (SIGINT) to save and shut down cleanly. A plain kill — or a SECOND
// Ctrl+C (the log literally says "CTRL-C TO FORCE QUIT") — skips the save and can corrupt the world.
// BeforeServiceStopped runs before the handler, so this delivers exactly one Ctrl+C and waits for the
// save to finish (it must be the SOLE Ctrl+C source — the blueprint StopCommand is cleared, because the
// built-in FindWineProcess path signals the wrong/many processes).
//   * Linux/Wine: SCUMServer.exe runs behind a `start.exe /exec` wrapper, and the monitor's tracked
//     PID is that wrapper (signalling it does nothing). Send ONE native SIGINT to the real
//     SCUMServer.exe process — wine forwards it as a console Ctrl+C, firing SCUM's ConsoleCtrl handler.
//   * Windows: use windows-kill.exe (Windows has no simple "send Ctrl+C to another process").

string RunBash(string cmd)
{
    var psi = new ProcessStartInfo { FileName = "/bin/bash", UseShellExecute = false, RedirectStandardOutput = true, RedirectStandardError = true };
    psi.ArgumentList.Add("-c");
    psi.ArgumentList.Add(cmd);
    using var p = Process.Start(psi);
    string o = p.StandardOutput.ReadToEnd();
    p.WaitForExit();
    return o;
}

if (System.OperatingSystem.IsLinux())
{
    // Scope to THIS service so multiple SCUM servers on one host never cross-signal: every SCUM
    // process (the start.exe launcher AND the game) carries this service's root directory in its
    // args. Match it slash-agnostically — wine shows the path as `Z:\...\` (backslashes) while the
    // launcher uses `/...` (forward). The real game = the matching SCUMServer.exe that is NOT the
    // start.exe wrapper; lowest PID is the main process (its workers have higher PIDs). Send ONE
    // SIGINT only (a second Ctrl+C force-quits SCUM without saving).
    string rootNorm = ThisService.RootDirectory.Replace('\\', '/');
    if (!rootNorm.EndsWith("/")) rootNorm += "/";   // trailing slash = path boundary (so /189/ != /1890/)

    int gamePid = -1;
    foreach (var raw in RunBash("ps -eo pid=,args=").Split('\n'))
    {
        var line = raw.Trim();
        int sp = line.IndexOf(' ');
        if (sp <= 0) continue;
        if (!int.TryParse(line.Substring(0, sp), out int pid)) continue;
        string argsNorm = line.Substring(sp + 1).Replace('\\', '/');
        if (argsNorm.IndexOf("SCUMServer.exe", StringComparison.OrdinalIgnoreCase) < 0) continue; // a SCUM process
        if (!argsNorm.Contains(rootNorm)) continue;                                               // belongs to THIS service
        if (argsNorm.IndexOf("start.exe", StringComparison.OrdinalIgnoreCase) >= 0) continue;     // skip the launcher
        if (gamePid < 0 || pid < gamePid) gamePid = pid;                                          // main game = lowest PID
    }

    if (gamePid < 0)
    {
        ScriptConsole.WriteLine("[scum-stop] No running SCUMServer.exe for this service; nothing to stop.");
        return;
    }

    ScriptConsole.WriteLine($"[scum-stop] Sending one SIGINT (Ctrl+C) to this service's SCUMServer.exe pid {gamePid} for a clean save + shutdown.");
    RunBash($"kill -INT {gamePid}");

    // Wait up to 180s for SCUM to finish saving and exit. Do NOT send a second SIGINT (it force-quits).
    for (int i = 1; i <= 180; i++)
    {
        string alive = RunBash($"kill -0 {gamePid} 2>/dev/null && echo yes || echo no").Trim();
        if (alive == "no")
        {
            ScriptConsole.WriteLine($"[scum-stop] SCUMServer.exe ({gamePid}) saved and exited after {i}s.");
            return;
        }
        await Task.Delay(TimeSpan.FromSeconds(1), ThisCancellationToken);
    }
    ScriptConsole.WriteLine("[scum-stop] WARNING: SCUMServer.exe did not exit within 180s.");
    return;
}

// Windows: windows-kill.exe (downloaded by the provisioning script).
int? pid = ThisService.ProcessId;
if (pid == null || pid <= 0)
{
    ScriptConsole.WriteLine("No running process id for this service; nothing to stop.");
    return;
}

string killExe = Path.Combine(ThisService.RootDirectory, "windows-kill.exe");
if (!File.Exists(killExe))
{
    ScriptConsole.WriteLine($"windows-kill.exe not found at {killExe}; skipping graceful Ctrl+C stop.");
    return;
}

ScriptConsole.WriteLine($"Sending SIGINT (Ctrl+C) to process {pid} via windows-kill.exe");
var wpsi = new ProcessStartInfo
{
    FileName = killExe,
    Arguments = $"-SIGINT {pid}",
    WorkingDirectory = ThisService.RootDirectory,
    UseShellExecute = false,
    CreateNoWindow = true,
    RedirectStandardOutput = true,
    RedirectStandardError = true
};
try
{
    using var killer = Process.Start(wpsi);
    if (killer != null)
        await killer.WaitForExitAsync(ThisCancellationToken);
}
catch (Exception ex)
{
    ScriptConsole.WriteLine($"Failed to run windows-kill.exe: {ex.Message}");
    return;
}

for (int count = 1; count <= 180; count++)
{
    bool running;
    try { using var proc = Process.GetProcessById(pid.Value); running = !proc.HasExited; }
    catch (ArgumentException) { running = false; }
    if (!running)
    {
        ScriptConsole.WriteLine($"Process {pid} has exited after {count} second(s).");
        return;
    }
    await Task.Delay(TimeSpan.FromSeconds(1), ThisCancellationToken);
}
ScriptConsole.WriteLine("WARNING: process did not exit within 180s.");

//refAssemblies: TCAdmin.SDK.dll, TCAdmin.GameHosting.SDK.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll, TCAdmin.Web.Shared.dll
using System;
using System.IO;
using System.Linq;
using System.Text;
using TCAdmin.SDK.Hubs.Models.GameQuery;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// CustomQueryProtocol: V3 deserializes the ReturnValue into a GameQueryResponse (V2 returned qstat XML).
// The query subsystem injects the resolved query Address/Port; fall back to the service's own.
string address = Variables.Parse<string>("Address", ThisService.IPAddress);
int queryPort = Variables.Parse<int>("Port", ThisService.QueryPort);
string gameType = "SCUM";
string mapName = ThisService.Variables.Parse<string>("Map", "SCUM") ?? "SCUM";

// 1) Player count from the most recent login_*.log (joins minus leaves).
string rootDir = ThisService.RootDirectory;
string logDir = Path.Combine(rootDir, "SCUM", "Saved", "SaveFiles", "Logs");
int joins = 0;
int leaves = 0;
try
{
    if (Directory.Exists(logDir))
    {
        string latest = Directory.GetFiles(logDir, "login_*.log")
            .OrderByDescending(f => f)
            .FirstOrDefault();
        if (latest != null)
        {
            // SCUM writes these logs as UTF-16LE (with BOM); ReadAllLines honours the BOM.
            foreach (string line in File.ReadAllLines(latest, Encoding.Unicode))
            {
                string l = line.ToLowerInvariant();
                if (l.Contains("logged in at")) joins++;
                else if (l.Contains("logged out at")) leaves++;
            }
        }
    }
}
catch (Exception ex)
{
    ScriptConsole.WriteLine($"player query: could not read login logs: {ex.Message}");
}

int numPlayers = Math.Max(0, joins - leaves);

// 2) ServerName + MaxPlayers from ServerSettings.ini.
string iniPath = Path.Combine(rootDir, "SCUM", "Saved", "Config", "WindowsServer", "ServerSettings.ini");
string serverName = "SCUM Server";
int maxPlayers = ThisService.Slots;
if (File.Exists(iniPath))
{
    try
    {
        foreach (string raw in File.ReadAllLines(iniPath))
        {
            string line = raw.Trim();
            if (line.StartsWith("scum.ServerName=", StringComparison.OrdinalIgnoreCase))
                serverName = line.Substring(line.IndexOf('=') + 1);
            else if (line.StartsWith("scum.MaxPlayers=", StringComparison.OrdinalIgnoreCase)
                     && int.TryParse(line.Substring(line.IndexOf('=') + 1).Trim(), out int mp))
                maxPlayers = mp;
        }
    }
    catch (Exception ex)
    {
        ScriptConsole.WriteLine($"player query: could not read ServerSettings.ini: {ex.Message}");
    }
}

Globals.ReturnValue = new GameQueryResponse
{
    Status = "online",
    Hostname = $"{address}:{queryPort}",
    Name = serverName,
    GameType = gameType,
    Map = mapName,
    NumPlayers = numPlayers,
    MaxPlayers = maxPlayers
};
